# retreat at 30% health normally, but at 50% when carrying gems
if not at_spawn and health() < 0.3 * max_health():
    if in_danger():
        let home = closest( spawn_region(ally()) )
        dash_to(0, home)
        dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not in_danger():
    recall()
    end_turn()

# ranged kiting: a ranged champion with an enemy champion adjacent steps away before attacking
let adj_enemy = nearest(enemies_visible())
if i_am_ranged() and exists(adj_enemy) and distance(unit_position(adj_enemy), position()) <= 1:
    move_away_from( unit_position(adj_enemy) )

let enemy = weakest( filter( enemies_visible(), in_attack_range() ) )
